import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] a = new int[n], freq = new int[n + 2], mark = new int[n + 2];
        for (int i = 0; i < n; i++) freq[a[i] = nextInt()]++;
        java.util.Arrays.fill(mark, -1);
        int mex = 0;
        while (freq[mex] > 0) mex++;
        int[] out = new int[n];
        int cnt = 0, i = 0;
        while (i < n) {
            // Take the MEX of the rest; cut the shortest prefix that covers 0..target-1.
            int target = mex, round = cnt, seen = 0;
            out[cnt++] = target;
            while (i < n) {
                int v = a[i++];
                if (--freq[v] == 0) mex = Math.min(mex, v);
                if (v < target && mark[v] != round) {
                    mark[v] = round;
                    seen++;
                }
                if (seen == target) break;
            }
        }
        StringBuilder sb = new StringBuilder();
        sb.append(cnt).append('\n');
        for (int k = 0; k < cnt; k++) {
            if (k > 0) sb.append(' ');
            sb.append(out[k]);
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int, n)
	freq := make([]int, n+2)
	mark := make([]int, n+2)
	for i := range a {
		a[i] = int(nextInt())
		freq[a[i]]++
	}
	for i := range mark {
		mark[i] = -1
	}
	mex := 0
	for freq[mex] > 0 {
		mex++
	}
	var out []int
	for i := 0; i < n; {
		// Take the MEX of the rest; cut the shortest prefix that covers 0..target-1.
		target, round, seen := mex, len(out), 0
		out = append(out, target)
		for i < n {
			v := a[i]
			i++
			freq[v]--
			if freq[v] == 0 {
				mex = min(mex, v)
			}
			if v < target && mark[v] != round {
				mark[v] = round
				seen++
			}
			if seen == target {
				break
			}
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(out)) + "\n")
	for k, v := range out {
		if k > 0 {
			w.WriteByte(' ')
		}
		w.WriteString(strconv.Itoa(v))
	}
	w.WriteByte('\n')
}
